#ifndef GX_STARTER_ANSWERS_H
#define GX_STARTER_ANSWERS_H
// Read-only starter answers. Exact normalized questions; no command execution.
struct StarterAnswer {const char* category;const char* phrase;const char* response;};
static const StarterAnswer gx_starter_answers[]={
  {"Getting started","how do i start using 360ai","Choose Assistant for instant local replies, or Models for GGUF chat. Home Y opens Quick tools for notes, timers and your own saved answers."},
  {"Getting started","what can i do without a model","Use predefined replies, saved answers, calculations, unit conversions, notes and session timers. These tools do not load model weights."},
  {"Getting started","how do i open quick tools","Press Y on Home, or Y in Assistant chat. Select a tool with the D-pad and press A."},
  {"Getting started","how do i enter text","Press A in Assistant chat, or X on Home. Use the console keyboard; START finishes an entry on the fallback keyboard."},
  {"Getting started","how do i return home","Press B to leave Assistant or a top-level tool screen. B first closes a waiting keyboard or confirmation."},
  {"Getting started","how do i use the controller menus","Move with the D-pad and press A on the highlighted item. The button prompts at the bottom show the available actions."},
  {"Getting started","where can i find the commands","Type help in Assistant, or open Command guide in Quick tools. ASSISTANT.txt in the USB ZIP has the full command guide."},
  {"Getting started","does assistant mode use gpu math","No. The instant assistant matches supported phrases and runs local tools. GPU matrix calculations apply to compatible GGUF model inference."},
  {"Getting started","can i use this without wifi","The instant assistant and installed models work offline. Hugging Face downloads and GitHub update checks need Internet access."},
  {"Getting started","does the assistant need an account","Local assistant tools and installed model chat need no account. The model library supports public ungated downloads without an account flow."},
  {"Getting started","does this replace my xbox dashboard","No. 360AI is a separate app launched through your existing XEX launcher. It does not replace the dashboard."},
  {"Getting started","where should i put the app files","Keep the extracted 360AI folder together on USB or HDD. Launch 360AI.xex and keep its models and updater beside it."},
  {"Getting started","what should i try first","Try hello, calculate 8 * 7, convert 5 miles to km, or remember to charge the controller. Quick tools offers controller shortcuts."},
  {"Getting started","why was my question not understood","This mode supports specific phrases and tools rather than arbitrary reasoning. Try help, browse Starter answers, or use a compatible GGUF model for broader text generation."},
  {"Getting started","can one message run several commands","Use one command per message. That makes note changes, calculations and timer requests easier to interpret reliably."},

  {"Notes","how do i save a note","Type remember followed by the note, or open Notes on Home and press X. Wait for Saved before closing the app after an edit."},
  {"Notes","where are my notes stored","Your notes, saved name and personal answers are stored in 360AI-assistant.json beside the app, with a previous valid .bak copy."},
  {"Notes","how many notes can i keep","You can keep up to 32 notes, with up to 512 bytes of text in each. Read or edit them from the Notes screen."},
  {"Notes","how do i edit a saved note","Open Notes, select the note and press A. You can also type edit note 1: new text, using the note's actual number."},
  {"Notes","how do i search my notes","Type find notes about batteries, replacing batteries with your search words. Every supplied whole word must appear in a matching note."},
  {"Notes","how do i read a long note","Open Notes, select it, and use LB/RB to page through its text. The right panel shows the full note."},
  {"Notes","how do i delete one note","Open Notes, select the note, press Y and confirm with A. A typed delete note command requires that note's exact number."},
  {"Notes","how do i recover a deleted note","Use undo immediately after the saved-data change, or START in the Notes screen. Undo keeps one change for the current app session."},
  {"Notes","why did a note number disappear","Note IDs are not reused after deletion or undo. The gaps help keep later commands from pointing at a different note."},
  {"Notes","do notes survive closing the app","Successfully saved notes survive closing and restarting. Wait for Saved after editing; Not saved means the current change is still only in memory."},
  {"Notes","can i save a multiline note","The save format supports multiline notes. On-screen rendering uses the console font, while the saved file preserves valid UTF-8 text."},
  {"Notes","what does not saved mean","The app could not write your assistant data to the drive. Your current data remains in memory; check that the drive is connected and writable."},
  {"Notes","do updates erase my notes","App-only updates replace the app executable and preserve personal files. Keep your own backup before manually replacing a folder."},
  {"Notes","can i keep separate notebooks on two drives","Each app folder uses its own assistant data file. Different folders or drives can therefore keep separate local notes and personal answers."},
  {"Notes","how do i back up my assistant data","Close the app after it reports Saved, then copy 360AI-assistant.json and its .bak file somewhere safe. Keep both outside a release ZIP replacement."},

  {"Timers","how do i start a timer","Open Timers on Home and press X, or type set timer 5 minutes called tea. Keep 360AI open for the alert."},
  {"Timers","how many timers can run together","Up to eight active or paused session timers can exist at once. Finished and cancelled timers free a slot."},
  {"Timers","do timers keep running after i exit","No. These are app-session timers, not Xbox system alarms. Closing or restarting 360AI ends the session."},
  {"Timers","how do i pause a timer","Select it in Timers and press A, or type pause timer followed by its number or exact label."},
  {"Timers","how do i resume a paused timer","Select the paused timer and press A again. You can also type resume timer followed by its number or label."},
  {"Timers","how do i add a minute to a timer","Select the timer in the Timers screen and press RB. A typed extend timer tea by 1 minute also works with the correct label."},
  {"Timers","how do i restart a timer","Select the active timer and press LB, or type restart timer with its number or label. Restart uses its original duration plus extensions."},
  {"Timers","how do i cancel one timer","Select it in Timers, press Y and confirm. You can also type cancel timer followed by its exact number or label."},
  {"Timers","what happens when a timer finishes","The app shows a temporary banner and records an Assistant chat alert. Timer history lists recent completed alerts for this session."},
  {"Timers","will a timer make a sound","There is no audio alarm in this version. Watch for the on-screen banner while 360AI remains open."},
  {"Timers","can i name my timers","Yes. Try set timer 5 minutes called tea. Distinct labels make it easier to pause, extend or cancel the right timer."},
  {"Timers","why did you ask which timer","More than one timer matched, or the selector was unclear. Reply with the exact timer number shown in the list."},
  {"Timers","what does it mean in timer commands","It refers to the most recently created or selected timer in this chat. That reference clears when the timer ends, is cancelled, or the chat resets."},
  {"Timers","what timer durations are supported","A timer can run from one second to seven days, while the app stays open. Compound durations such as 1h30m are supported."},
  {"Timers","can i see completed timer alerts","Type timer history for the last eight completed alerts in the current session. History is cleared when the app closes."},

  {"Personal answers","how do i make my own reply","Open Saved answers from Quick tools, press X, enter a phrase, then enter its reply. Nothing is saved until both fields are valid."},
  {"Personal answers","how do i change a personal answer","Open Saved answers, choose My answers, select the phrase and press A. Edit the reply and finish the keyboard entry."},
  {"Personal answers","how many personal answers can i save","There are 16 personal answer slots, separate from the 150 read-only starter answers. Personal replies can customize matching starter text."},
  {"Personal answers","how long can my answer phrase be","Use a normalized phrase of 3-80 bytes and a reply of 1-512 bytes. Case and ordinary punctuation are ignored when matching."},
  {"Personal answers","what happens if i enter a duplicate phrase","The new-answer flow selects the existing personal phrase and asks you to edit it. It does not silently replace its reply."},
  {"Personal answers","how do i test a reply without running it","Click the right stick in Saved answers and enter a sentence. The preview matches text without running commands, timers, models or network requests."},
  {"Personal answers","can an answer execute a command","No. Saved replies are literal text. A reply saying delete all notes does not delete anything or trigger another command."},
  {"Personal answers","why does my saved reply not override a command","Built-in commands keep priority so saved text cannot replace actions. Use a different phrase for your personal reply."},
  {"Personal answers","how do i delete a personal answer","In My answers, select the phrase, press Y and confirm. START can undo the latest saved-data change during this session."},
  {"Personal answers","can i undo an answer edit","Yes. START in Saved answers, or the undo command, restores the last change to notes, your name or personal answers. It is a single session-level undo."},
  {"Personal answers","can i customize a starter answer","Choose Starter answers, select a question and press A. Edit the copied reply and save it into a personal slot; the original starter remains available."},
  {"Personal answers","will a cancelled draft replace my answer","No. Cancelling a phrase or reply keyboard keeps existing answers unchanged. Finish a valid reply to save the edit."},
  {"Personal answers","why does a longer saved phrase win","Personal matching uses whole words and prefers the longest matching saved phrase. More specific phrases can distinguish related questions."},
  {"Personal answers","does teaching an answer train a neural model","No. It saves an explicit phrase and text reply on your drive. It needs no model weights, training run or Internet access."},
  {"Personal answers","what happens if i remove a customized starter","The personal override is removed, so its built-in starter reply is available again. The original starter pack is never changed by personal edits."},

  {"Local models","which bundled model should i try for chat","SmolLM2 135M is the recommended starting point for local instruction chat. Leave compute and storage on Auto and use Quick for short replies."},
  {"Local models","what are the tinystories models for","They are tiny story-completion toys. Try an opening such as Once upon a time; they are not reliable instruction-following chat assistants."},
  {"Local models","why does the tiny model produce nonsense","The smallest TinyStories model trades most language capability for very little work. Small size does not make it a useful general assistant."},
  {"Local models","where do local gguf files go","Keep GGUF files beside 360AI.xex. Keep every shard of a split model together and select its first shard."},
  {"Local models","how do i load a local model","Open Models, select a file, press A for setup, and choose Load model. Auto compute and storage are a useful starting point."},
  {"Local models","how do i sort the local model list","Press LB in Models to switch smallest-first and name ordering. The selection follows the same file when its list position changes."},
  {"Local models","what does gguf mean here","GGUF is the model-file format read by this app. Architecture, tensor formats, tokenizer and working-memory limits still determine compatibility."},
  {"Local models","can i run every gguf model","No. This engine supports compatible dense Llama, SmolLM2, Qwen2/2.5 and Gemma 2/3 models. Other architectures and unsupported tensor formats are rejected."},
  {"Local models","can hdd space replace all model ram","No. Streaming can keep matrix weights on disk, but tokenizer data, scratch buffers and the KV cache still need RAM."},
  {"Local models","why does a model need every split file","Each shard contains part of the model. Missing shards leave required weights unavailable, so keep the complete matching group together."},
  {"Local models","what should i do after a model load fails","Read 360AI.log for the failure, try a smaller compatible model or context, and confirm that all required shards are present."},
  {"Local models","does a smaller file always mean faster chat","No. File size, architecture, quantization, memory use and storage behavior all matter. Use measured console behavior rather than file size alone."},
  {"Local models","what does context size control","Context reserves space for prompt and reply tokens in the KV cache. A larger context uses more working memory and can add processing work."},
  {"Local models","what does the reply limit control","It caps how many new tokens the console model may generate. A lower cap can shorten the wait for a complete reply without making each token faster."},
  {"Local models","can the instant assistant use my gguf knowledge","The instant assistant does not read or run GGUF weights. Choose Models for model generation, or save explicit personal replies for instant matching."}
};
#endif
